import{_ as i,c as t,o as r,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Addressing The Threat To National Security from Imports of Timber, Lumber","description":"","frontmatter":{"title":"Addressing The Threat To National Security from Imports of Timber, Lumber","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/addressing-the-threat-to-national-security-from-imports-of-timber-lumber/","publishDate":"2025-03-01"},"headers":[],"relativePath":"executive-orders/2025-03-01-addressing-the-threat-to-national-security-from-imports-of-timber-lumber.md","filePath":"executive-orders/2025-03-01-addressing-the-threat-to-national-security-from-imports-of-timber-lumber.md"}'),a={name:"executive-orders/2025-03-01-addressing-the-threat-to-national-security-from-imports-of-timber-lumber.md"};function s(n,e,l,d,u,c){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="addressing-the-threat-to-national-security-from-imports-of-timber-lumber" tabindex="-1">Addressing The Threat To National Security from Imports of Timber, Lumber <a class="header-anchor" href="#addressing-the-threat-to-national-security-from-imports-of-timber-lumber" aria-label="Permalink to &quot;Addressing The Threat To National Security from Imports of Timber, Lumber&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/addressing-the-threat-to-national-security-from-imports-of-timber-lumber/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/addressing-the-threat-to-national-security-from-imports-of-timber-lumber/</a></p><p>Published: Friday, February 28, 2025</p><h2 id="summary-of-executive-order-on-wood-products-industry" tabindex="-1">Summary of Executive Order on Wood Products Industry <a class="header-anchor" href="#summary-of-executive-order-on-wood-products-industry" aria-label="Permalink to &quot;Summary of Executive Order on Wood Products Industry&quot;">​</a></h2><h3 id="policy" tabindex="-1"><strong>Policy</strong> <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;**Policy**&quot;">​</a></h3><ul><li>The wood products industry (timber, lumber, and derivatives) is critical to national security and economic resilience.</li><li>The U.S. faces vulnerabilities due to imported timber and lumber being dumped in the market.</li><li>The U.S. has sufficient timber resources and can meet 95% of domestic softwood demand but has been a net importer since 2016.</li><li>Wood products are essential for both civilian construction and military infrastructure.</li><li>The U.S. aims to secure reliable domestic supply chains and address unfair foreign trade practices under Section 232 of the Trade Expansion Act.</li></ul><h3 id="investigation" tabindex="-1"><strong>Investigation</strong> <a class="header-anchor" href="#investigation" aria-label="Permalink to &quot;**Investigation**&quot;">​</a></h3><ul><li>The <strong>Secretary of Commerce</strong> must investigate the effects of timber, lumber, and derivative imports on national security.</li><li>The investigation will assess: <ul><li>U.S. demand and domestic production capabilities.</li><li>Dependence on foreign supply chains.</li><li>Impact of foreign subsidies and trade practices.</li><li>Potential for increasing domestic production.</li><li>Necessity of additional trade measures like tariffs or quotas.</li></ul></li></ul><h3 id="required-actions" tabindex="-1"><strong>Required Actions</strong> <a class="header-anchor" href="#required-actions" aria-label="Permalink to &quot;**Required Actions**&quot;">​</a></h3><ul><li>The <strong>Secretary of Commerce</strong> will consult with the <strong>Secretary of Defense</strong> and other relevant agencies.</li><li>A report must be submitted within <strong>270 days</strong>, including: <ul><li>Findings on whether imports threaten national security.</li><li>Recommendations on actions such as tariffs, export controls, or incentives.</li><li>Policy proposals for strengthening domestic supply chains through investment and permitting reforms.</li></ul></li></ul><h3 id="definitions" tabindex="-1"><strong>Definitions</strong> <a class="header-anchor" href="#definitions" aria-label="Permalink to &quot;**Definitions**&quot;">​</a></h3><ul><li><strong>Timber</strong>: Unprocessed wood.</li><li><strong>Lumber</strong>: Processed wood, including milled and cut boards/planks.</li></ul><h3 id="general-provisions" tabindex="-1"><strong>General Provisions</strong> <a class="header-anchor" href="#general-provisions" aria-label="Permalink to &quot;**General Provisions**&quot;">​</a></h3><ul><li>This order does not override existing laws or agency authorities.</li><li>Implementation depends on legal compliance and budget availability.</li><li>No legal rights or benefits are created for any party.</li></ul><p><strong>Issued: March 1, 2025 – The White House</strong></p>',15)]))}const f=i(a,[["render",s]]);export{h as __pageData,f as default};
